-- bangkok: checked place by place on 2026-10-25 (still open, own websites, prices with sources).

UPDATE "Place" p SET "area" = 'Ratchaburi & Samut Songkhram' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'bangkok' AND p.slug = 'damnoen-saduak-maeklong';
UPDATE "Place" p SET "area" = 'Ratchaprasong' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'bangkok' AND p.slug = 'erawan-shrine';
UPDATE "Place" p SET "name" = 'Jodd Fairs Ratchada', "area" = 'Ratchada', "lat" = 13.766, "lng" = 100.57, "tip" = 'Moved from Rama 9 to Ratchada, next to Thailand Cultural Centre MRT, in 2025.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'bangkok' AND p.slug = 'jodd-fairs';
